using System.Collections.Generic;

namespace Screenbox.Core.Playback;

/// <summary>
/// Tracks which VLC subtitle ES ids belong to files generated by the subtitle resizer, so that
/// they never reach the subtitle menu or move its selection.
/// </summary>
/// <remarks>
/// <para>
/// A generated track is recognised by the ES that appears after its file is added. The resizer
/// says a file is coming (<see cref="Expect"/>) just before calling AddSlave, and the next text ES
/// that VLC reports with an id no known track has is that file. This relies on two things measured
/// against LibVLC 3.0.23: ES ids come from a counter that keeps rising for the life of the input,
/// so an id is never reused and never collides with an embedded track, and a slave's ES is reported
/// by ESAdded before it is selected.
/// </para>
/// <para>
/// The track's name cannot do this job. VLC names a slave's language after the part of its path
/// between the last two dots, but the app opens files through a <c>winrt://</c> access token, which
/// has no file name in it for VLC to read.
/// </para>
/// <para>VLC raises its events on its own threads, so access is locked.</para>
/// </remarks>
internal sealed class GeneratedSubtitleTracks
{
    private readonly object _lock = new();
    private readonly HashSet<int> _esIds = new();
    private int _expected;

    /// <summary>Notes that a generated file is about to be added.</summary>
    public void Expect()
    {
        lock (_lock)
        {
            _expected++;
        }
    }

    /// <summary>Withdraws an expectation for a file that VLC refused, so no ES will follow it.</summary>
    public void CancelExpected()
    {
        lock (_lock)
        {
            if (_expected > 0) _expected--;
        }
    }

    /// <summary>
    /// Decides whether a newly reported text ES is a generated one, and remembers it if so.
    /// </summary>
    /// <param name="esId">The ES id VLC reported.</param>
    /// <param name="isKnownTrack">Whether a track in the subtitle list already has this id.</param>
    /// <returns>True when the ES is generated and must be kept out of the track list.</returns>
    public bool TryClaim(int esId, bool isKnownTrack)
    {
        lock (_lock)
        {
            if (_esIds.Contains(esId)) return true;
            if (_expected == 0 || isKnownTrack) return false;

            _expected--;
            _esIds.Add(esId);
            return true;
        }
    }

    /// <summary>Returns whether an ES id belongs to a generated file.</summary>
    public bool Contains(int esId)
    {
        lock (_lock)
        {
            return _esIds.Contains(esId);
        }
    }

    /// <summary>
    /// Forgets everything. Called when the input restarts: VLC drops its slaves and starts counting
    /// ES ids again, so an old id could come back as a subtitle the user added.
    /// </summary>
    public void Reset()
    {
        lock (_lock)
        {
            _esIds.Clear();
            _expected = 0;
        }
    }
}
